    /// Returns `total_elapsed_time` in its scaled value. It returns `None` when value is invalid.
    ///
    /// Units: s
    pub fn total_elapsed_time_scaled(&self) -> Option<f64> {
        if self.total_elapsed_time == u32::MAX {
            return None;
        }
        Some(self.total_elapsed_time as f64 / 1000.0 - 0.0)
    }

    /// Set `total_elapsed_time` with scaled value, it will automatically be converted to its corresponding integer value.
    pub fn set_total_elapsed_time_scaled(&mut self, v: f64) -> &mut Self {
        let unscaled = (v + 0.0) * 1000.0;
        if unscaled.is_nan() || unscaled.is_infinite() || unscaled > u32::MAX as f64 {
            self.total_elapsed_time = u32::MAX;
            return self;
        }
        self.total_elapsed_time = unscaled as u32;
        self
    }

